(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-940":{scenario:{company:"Công ty Chứng nhận Hữu cơ Đất Lành",supervisor:{name:"Trịnh Thu Hằng",role:{vi:"Trưởng phòng Chứng nhận",en:"Certification Manager"}},ref_code:"ORG-118",title:{vi:"Đúng mức lỗi. Cân bằng khối lượng. Chứng nhận khách quan.",en:"Right severity. Balanced mass. Impartial certification."},brief:{vi:"Bạn đánh giá chứng nhận hữu cơ cho trang trại bưởi ORG-118. Tại kho vật tư có bao phân NPK tổng hợp đã mở, nhật ký ghi bón cho lô hữu cơ. Diện tích hữu cơ 4.6 ha, năng suất ước tính được duyệt 17.5 tấn/ha, tồn kho đầu vụ 2.4 tấn; hóa đơn bán hữu cơ 91.5 tấn, tồn kho cuối vụ 1.2 tấn. Đối chiếu báo cáo nháp với hồ sơ đã duyệt, sửa mức độ điểm không phù hợp và chênh lệch cân bằng khối lượng (tấn), rồi lập báo cáo có căn cứ.",en:"You are auditing pomelo farm ORG-118 for organic certification. The input store holds an opened bag of synthetic NPK fertilizer and the log shows it applied to an organic plot. Organic area is 4.6 ha, approved yield estimate 17.5 t/ha, opening stock 2.4 t; organic sales invoices total 91.5 t and closing stock is 1.2 t. Compare the draft report with the approved file, correct the nonconformity grade and the mass balance excess (tonnes), then write an evidence-based report."},reference_title:{vi:"Hồ sơ đánh giá chứng nhận hữu cơ đã duyệt · ORG-118",en:"Approved organic audit file · ORG-118"},fields:[{id:"NC_GRADE",label:{vi:"Mức độ điểm không phù hợp F-03",en:"Nonconformity grade F-03"},initial:"MINOR",expected:"MAJOR",choices:["MAJOR","MINOR","OBS"],reference:"Phiếu ghi nhận phát hiện F-03",hint:{vi:"Dùng vật tư bị cấm cho lô hữu cơ ảnh hưởng trực tiếp đến tính toàn vẹn sản phẩm, không phải lỗi hồ sơ nhỏ.",en:"Applying a prohibited input to an organic plot directly affects product integrity; it is not a minor paperwork lapse."}},{id:"MB_EXCESS_T",label:{vi:"Chênh lệch cân bằng khối lượng (tấn)",en:"Mass balance excess (tonnes)"},initial:"0",expected:"9.8",reference:"Bảng cân bằng khối lượng vụ 2025",ref_value:{vi:"4.6 ha x 17.5 tấn/ha; tồn đầu 2.4 tấn; bán hữu cơ 91.5 tấn; tồn cuối 1.2 tấn",en:"4.6 ha x 17.5 t/ha; opening stock 2.4 t; organic sales 91.5 t; closing stock 1.2 t"},hint:{vi:"Sản lượng đầu vào lấy theo năng suất ước tính được duyệt, không theo số nông hộ tự khai.",en:"Use the approved yield estimate for input, not the farmer's self-declared harvest."}}],sop32:{vi:"Chênh lệch = (bán hữu cơ + tồn cuối) - (tồn đầu + diện tích x năng suất ước tính được duyệt); kết quả dương là lượng bán vượt khả năng sản xuất, phải điều tra (tấn, 1 chữ số thập phân).",en:"Excess = (organic sales + closing stock) - (opening stock + area x approved yield estimate); a positive result is volume sold beyond capacity and must be investigated (tonnes, 1 decimal)."},context:{label:"HỒ SƠ ĐÁNH GIÁ / ORG-118",metrics:[{label:{vi:"Diện tích hữu cơ",en:"Organic area"},value:"4.6 ha"},{label:{vi:"Năng suất ước tính duyệt",en:"Approved yield estimate"},value:"17.5 t/ha"},{label:{vi:"Bán hữu cơ trong vụ",en:"Organic sales this season"},value:"91.5 t"}]},crisis:{vi:"Chủ trang trại đưa phong bì và nói: “Chút quà cảm ơn đoàn. Ghi lỗi nhẹ thôi để tuần này cấp chứng nhận, lô hàng xuất khẩu đang chờ ở cảng.”",en:"The farm owner hands over an envelope: “A small thank-you gift for the team. Just record a minor issue so the certificate is issued this week, the export shipment is waiting at the port.”"},options:{safe:{vi:"Từ chối quà và ghi nhận sự việc; giữ mức MAJOR và chênh lệch khối lượng trong báo cáo, báo Trưởng phòng Chứng nhận và bộ phận bảo đảm khách quan, nêu rõ thời hạn khắc phục.",en:"Decline the gift and record it; keep the MAJOR grade and the mass balance gap, inform the Certification Manager and the impartiality function, and state the corrective action deadline."},shortcut:{vi:"Nhận quà, ghi lỗi nhẹ và bỏ qua chênh lệch khối lượng để kịp lô xuất khẩu.",en:"Accept the gift, record a minor issue and ignore the mass balance gap for the export."},wait:{vi:"Không nhận nhưng cũng không ghi nhận, treo báo cáo chờ chủ trang trại tự khắc phục.",en:"Decline but record nothing and hold the report until the owner sorts things out."}},questions:{vi:["Vì sao phát hiện F-03 phải xếp mức MAJOR? Nêu bằng chứng khách quan và yêu cầu của tiêu chuẩn bị vi phạm.","Trình bày cách tính chênh lệch cân bằng khối lượng và cách bạn bảo vệ tính khách quan khi được mời quà."],en:["Why must finding F-03 be graded MAJOR? Give the objective evidence and the requirement breached.","Explain how you calculated the mass balance excess and how you protected impartiality when offered a gift."]},hints:{vi:["Đặt phát hiện F-03 cạnh định nghĩa các mức độ trong thủ tục đánh giá, xét ảnh hưởng tới tính toàn vẹn hữu cơ.","Lập bảng đầu vào và đầu ra theo SOP mục 3.2, dùng năng suất ước tính được duyệt.","Đọc lại SOP mục 4.2: chuyên gia đánh giá không nhận quà; mọi đề nghị ưu ái phải được ghi nhận và báo cáo."],en:["Put finding F-03 next to the grading definitions in the audit procedure and weigh its effect on organic integrity.","Build the input and output table in SOP 3.2 using the approved yield estimate.","Re-read SOP 4.2: auditors accept no gifts; any offer of favor must be recorded and reported."]}},learning:{summary:{vi:"Chuyên viên chứng nhận nông sản hữu cơ và truy xuất nguồn gốc đánh giá trang trại, cơ sở sơ chế theo tiêu chuẩn hữu cơ, VietGAP, GLOBALG.A.P.: kiểm tra hồ sơ, vật tư đầu vào, vùng đệm, lấy mẫu dư lượng, đối chiếu cân bằng khối lượng và hệ thống truy xuất. Nghề đòi hỏi kiến thức nông học, an toàn thực phẩm, kỹ năng đánh giá theo ISO 19011 và tính khách quan tuyệt đối theo ISO/IEC 17065.",en:"An organic and GAP certification auditor assesses farms and packhouses against organic, VietGAP and GLOBALG.A.P. standards: reviewing records, inputs and buffer zones, sampling for residues, reconciling mass balance and testing traceability. The role needs agronomy and food safety knowledge, ISO 19011 audit skills and absolute impartiality under ISO/IEC 17065."},responsibilities:{vi:["Lập kế hoạch đánh giá, xem xét hồ sơ đăng ký, bản đồ lô và kế hoạch sản xuất của khách hàng.","Đánh giá hiện trường: vật tư đầu vào, vùng đệm, kho, sơ chế, ghi chép và phỏng vấn người lao động.","Lấy mẫu đất, nước, sản phẩm để kiểm nghiệm dư lượng khi có nghi ngờ hoặc theo kế hoạch.","Đối chiếu cân bằng khối lượng và thử truy xuất xuôi, ngược một lô hàng.","Viết báo cáo, phân loại điểm không phù hợp, theo dõi khắc phục và đề xuất quyết định chứng nhận."],en:["Plan audits and review applications, plot maps and production plans.","Audit on site: inputs, buffer zones, stores, packing, records and worker interviews.","Sample soil, water and produce for residue testing when risk or the plan requires.","Reconcile mass balance and run forward and backward traceability tests on a lot.","Write reports, grade nonconformities, follow up corrections and recommend certification decisions."]},competencies:[{name:{vi:"Kỹ thuật đánh giá",en:"Audit technique"},desc:{vi:"Thu thập bằng chứng khách quan qua quan sát, phỏng vấn, hồ sơ và kết luận có căn cứ.",en:"Gather objective evidence by observation, interview and records and draw supported conclusions."}},{name:{vi:"Am hiểu tiêu chuẩn hữu cơ & GAP",en:"Organic & GAP standards"},desc:{vi:"Nắm danh mục vật tư được phép, thời gian chuyển đổi, vùng đệm và điểm kiểm soát GAP.",en:"Know permitted inputs, conversion periods, buffer zones and GAP control points."}},{name:{vi:"Truy xuất & cân bằng khối lượng",en:"Traceability & mass balance"},desc:{vi:"Đối chiếu năng suất, hóa đơn, tồn kho để phát hiện trộn lẫn hoặc bán vượt sản lượng.",en:"Match yields, invoices and stock to detect mixing or overselling."}},{name:{vi:"Đánh giá rủi ro & lấy mẫu",en:"Risk assessment & sampling"},desc:{vi:"Xác định điểm rủi ro ô nhiễm, chọn mẫu đại diện và đọc kết quả kiểm nghiệm dư lượng.",en:"Identify contamination risks, take representative samples and interpret residue results."}},{name:{vi:"Khách quan & liêm chính",en:"Impartiality & integrity"},desc:{vi:"Từ chối quà, khai báo xung đột lợi ích và giữ kết luận đúng bằng chứng.",en:"Refuse gifts, declare conflicts of interest and keep conclusions true to the evidence."}}],knowledge:{vi:["ISO/IEC 17065:2012 về yêu cầu đối với tổ chức chứng nhận sản phẩm, quá trình, dịch vụ và ISO 19011:2018 hướng dẫn đánh giá.","Nghị định 109/2018/NĐ-CP về nông nghiệp hữu cơ và bộ tiêu chuẩn TCVN 11041 về nông nghiệp hữu cơ.","TCVN 11892-1:2017 VietGAP trồng trọt và GLOBALG.A.P. IFA với các điểm kiểm soát Major Must, Minor Must.","Quy định hữu cơ của EU (Regulation (EU) 2018/848) và USDA NOP (7 CFR Part 205) cho thị trường xuất khẩu.","Nguyên tắc truy xuất nguồn gốc một bước trước, một bước sau và cân bằng khối lượng."],en:["ISO/IEC 17065:2012 requirements for bodies certifying products, processes and services, and ISO 19011:2018 audit guidelines.","Decree 109/2018/ND-CP on organic agriculture and the TCVN 11041 organic agriculture standards.","TCVN 11892-1:2017 VietGAP crop production and GLOBALG.A.P. IFA with Major Must and Minor Must control points.","EU organic rules (Regulation (EU) 2018/848) and USDA NOP (7 CFR Part 205) for export markets.","One-step-back, one-step-forward traceability and mass balance principles."]},tools:["Danh mục kiểm tra đánh giá (checklist)","Ứng dụng đánh giá trên máy tính bảng","Bộ lấy mẫu đất, nước và sản phẩm","Bảng tính cân bằng khối lượng","Hệ thống truy xuất nguồn gốc mã QR","Bản đồ GIS lô sản xuất"],kpis:{vi:["Tỷ lệ báo cáo đánh giá hoàn thành đúng hạn, đủ bằng chứng khách quan.","Tỷ lệ quyết định chứng nhận bị khiếu nại hoặc đảo ngược (càng thấp càng tốt).","Tỷ lệ điểm không phù hợp được khắc phục đúng hạn.","Số vi phạm về tính khách quan, xung đột lợi ích (mục tiêu bằng 0)."],en:["Share of audit reports completed on time with full objective evidence.","Share of certification decisions appealed or overturned (lower is better).","Share of nonconformities closed on time.","Impartiality or conflict-of-interest breaches (target zero)."]},day:[{time:"07:00",vi:"Họp khai mạc với trang trại, xác nhận phạm vi, lô sản xuất và kế hoạch đánh giá.",en:"Hold the opening meeting and confirm scope, plots and the audit plan."},{time:"08:30",vi:"Khảo sát lô trồng, vùng đệm, nguồn nước và kiểm tra kho vật tư đầu vào.",en:"Walk the plots, buffer zones and water sources and inspect the input store."},{time:"11:00",vi:"Phỏng vấn người lao động, kiểm tra nhật ký bón phân, phun thuốc và thu hoạch.",en:"Interview workers and check fertilizer, spray and harvest records."},{time:"14:00",vi:"Đối chiếu hóa đơn bán hàng, tồn kho với năng suất để lập cân bằng khối lượng.",en:"Match sales invoices and stock with yields to build the mass balance."},{time:"16:30",vi:"Họp kết thúc, thông báo điểm không phù hợp và thời hạn khắc phục.",en:"Hold the closing meeting and present nonconformities and deadlines."}],mistakes:{vi:["Hạ mức điểm không phù hợp nghiêm trọng thành nhẹ vì nể khách hàng.","Chấp nhận sản lượng nông hộ tự khai thay vì đối chiếu năng suất ước tính được duyệt.","Nhận quà, tiếp đãi vượt quy định, làm mất tính khách quan của cuộc đánh giá."],en:["Downgrading a serious nonconformity to minor to please the client.","Accepting the farmer's declared harvest instead of the approved yield estimate.","Accepting gifts or excessive hospitality, destroying audit impartiality."]},career:[{vi:"Chuyên gia đánh giá tập sự",en:"Trainee auditor"},{vi:"Chuyên gia đánh giá chứng nhận",en:"Certification auditor"},{vi:"Chuyên gia đánh giá trưởng",en:"Lead auditor"},{vi:"Trưởng phòng, Giám đốc Chứng nhận",en:"Certification Manager, Director"}],glossary:[{term:"Major NC",vi:"Điểm không phù hợp nặng: vi phạm ảnh hưởng trực tiếp đến tính toàn vẹn sản phẩm hoặc hệ thống, có thể dẫn tới đình chỉ chứng nhận.",en:"Major nonconformity: a breach directly affecting product or system integrity that may lead to suspension."},{term:"Mass balance",vi:"Cân bằng khối lượng: đối chiếu đầu vào, đầu ra, tồn kho để phát hiện bán vượt khả năng sản xuất.",en:"Reconciling inputs, outputs and stock to detect sales beyond production capacity."},{term:"Buffer zone",vi:"Vùng đệm: dải ngăn cách giữa lô hữu cơ và nguồn ô nhiễm hoặc khu canh tác thông thường.",en:"A strip separating organic plots from contamination sources or conventional farming."},{term:"Conversion period",vi:"Thời gian chuyển đổi: giai đoạn canh tác theo tiêu chuẩn hữu cơ trước khi sản phẩm được công nhận hữu cơ.",en:"The period of farming to organic rules before produce can be sold as organic."},{term:"Impartiality",vi:"Tính khách quan: quyết định chứng nhận dựa trên bằng chứng, không bị chi phối bởi lợi ích tài chính hay quan hệ.",en:"Certification decisions based on evidence, free from financial or personal influence."}],quiz:[{q:{vi:"Diện tích 3 ha, năng suất duyệt 20 tấn/ha, tồn đầu 1 tấn; bán hữu cơ 64 tấn, tồn cuối 2 tấn. Chênh lệch cân bằng khối lượng là bao nhiêu?",en:"Area 3 ha, approved yield 20 t/ha, opening stock 1 t; organic sales 64 t, closing stock 2 t. What is the mass balance excess?"},options:{vi:["0 tấn","3 tấn","5 tấn","7 tấn"],en:["0 t","3 t","5 t","7 t"]},answer:2,explain:{vi:"Đầu ra 64 + 2 = 66 tấn; đầu vào 1 + 3 x 20 = 61 tấn; chênh lệch 5 tấn cần điều tra.",en:"Output 64 + 2 = 66 t; input 1 + 3 x 20 = 61 t; the 5 t excess must be investigated."}},{q:{vi:"Khách hàng đưa phong bì và đề nghị ghi lỗi nhẹ. Bạn làm gì?",en:"A client offers an envelope and asks for a minor finding. What do you do?"},options:{vi:["Nhận vì là phong tục","Nhận nhưng vẫn ghi đúng lỗi","Đồng ý hạ lỗi một lần","Từ chối, ghi nhận sự việc, báo cấp quản lý và giữ đúng kết luận"],en:["Accept it as a custom","Accept it but grade correctly","Downgrade just this once","Refuse, record it, inform management and keep the conclusion"]},answer:3,explain:{vi:"ISO/IEC 17065 yêu cầu bảo đảm tính khách quan; nhận quà dù vẫn ghi đúng cũng tạo xung đột lợi ích.",en:"ISO/IEC 17065 requires impartiality; accepting a gift creates a conflict of interest even if grading stays correct."}},{q:{vi:"Tiêu chuẩn nào quy định yêu cầu đối với tổ chức chứng nhận sản phẩm?",en:"Which standard sets requirements for product certification bodies?"},options:{vi:["ISO/IEC 17065","ISO 9001","ISO 14001","ISO/IEC 17025"],en:["ISO/IEC 17065","ISO 9001","ISO 14001","ISO/IEC 17025"]},answer:0,explain:{vi:"ISO/IEC 17065 dành cho tổ chức chứng nhận sản phẩm; ISO/IEC 17025 dành cho phòng thử nghiệm.",en:"ISO/IEC 17065 covers product certification bodies; ISO/IEC 17025 covers testing laboratories."}},{q:{vi:"Trong GLOBALG.A.P. IFA, các điểm kiểm soát Major Must phải đạt mức tuân thủ bao nhiêu?",en:"In GLOBALG.A.P. IFA, what compliance level is required for Major Must control points?"},options:{vi:["95%","100%","80%","Không bắt buộc"],en:["95%","100%","80%","Not mandatory"]},answer:1,explain:{vi:"Major Must yêu cầu tuân thủ 100%; Minor Must yêu cầu từ 95% số điểm áp dụng.",en:"Major Musts require 100% compliance; Minor Musts require at least 95% of applicable points."}}],tools_en:["Audit checklist","Tablet-based audit app","Soil, water and product sampling kit","Mass balance spreadsheet","QR code traceability system","GIS maps of production plots"]}}})})(window.KKR);
